WITH carcinogenic_molecules AS (
    SELECT DISTINCT molecule FROM molecule WHERE molecule IN (
        SELECT molecule FROM bond WHERE evidence = '+'
    )
),
carcinogenic_fluorine_molecules AS (
    SELECT DISTINCT m.molecule
    FROM carcinogenic_molecules m
    JOIN atom a ON m.molecule = a.molecule
    WHERE a.symbol = 'F'
)
SELECT ROUND(
    (CAST((SELECT COUNT(*) FROM carcinogenic_molecules WHERE molecule NOT IN (SELECT molecule FROM carcinogenic_fluorine_molecules)) AS FLOAT) /
    (SELECT COUNT(*) FROM carcinogenic_molecules)) * 100, 2
) AS percentage_no_fluorine
;

